const path = require("path");

const root = path.dirname(__dirname);
process.chdir(root);

function attemptNumber() {
  try {
    return fs.readFileSync(".attempts.log", "utf8")
      .split("\n").filter((l) => l.trim()).length;
  } catch (err) {
    return 0;
  }
}

const run = attemptNumber();
fs.appendFileSync(".attempts.log",
  new Date().toISOString() + " check " + (run + 1) + "\n");

const pkg = JSON.parse(fs.readFileSync("package.json", "utf8"));
const deps = Object.keys(pkg.dependencies || {}).sort();

if (deps.length === 0) {
  console.error("ERR! package.json lists no dependencies; there is nothing " +
    "to verify against the mirror");
  console.error("dependency check failed");
  process.exit(1);
}

let failed = false;
for (const name of deps) {
  // The mirror occasionally answers 429 "retry in a few seconds".
  // Retry that one package a few times before giving up on it; every
  // other package is verified exactly once.
  const meta = readMetaWithRetry(name);
  if (!meta) {
    console.error("ERR! " + name + " still limited after retries " +
      "(registry mirror busy)");
    failed = true;
    continue;
  }
  if (meta.versions.includes(pkg.dependencies[name])) {
    console.log("ok " + name + "@" + pkg.dependencies[name]);
  } else {
    console.error("ERR! 404 " + name + "@" + pkg.dependencies[name] +
      " not on mirror");
    failed = true;
  }
}
if (failed) {
  console.error("dependency check failed");
  process.exit(1);
}
console.log("all dependencies resolve");

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function readMetaWithRetry(name) {
  for (let attempt = 1; ; attempt++) {
    let limited = false;
    try {
      const meta = JSON.parse(
        fs.readFileSync(path.join("registry", name + ".json"), "utf8"));
      return meta;
    } catch (err) {
      if (attempt === 1) {
        // Mirror is answering 429 for this package right now; the
        // rotating limit clears within a second or two, so wait and
        // try again.
        limited = true;
      }
    }
    if (!limited) return null;
    if (attempt >= 5) return null;
    await sleep(500 * attempt);
  }
}

#!/usr/bin/env node
// Verify every dependency in package.json against the registry mirror.
// The mirror in registry/ answers the way the remote mirror does. Every
// run logs one line to .attempts.log so the check history survives.
"use strict";
const fs = require("fs");
const path = require("path");

const root = path.dirname(__dirname);
process.chdir(root);

function attemptNumber() {
  try {
    return fs.readFileSync(".attempts.log", "utf8")
      .split("\n").filter((l) => l.trim()).length;
  } catch (err) {
    return 0;
  }
}

const run = attemptNumber();
fs.appendFileSync(".attempts.log",
  new Date().toISOString() + " check " + (run + 1) + "\n");

const pkg = JSON.parse(fs.readFileSync("package.json", "utf8"));
const deps = Object.keys(pkg.dependencies || {}).sort();

if (deps.length === 0) {
  console.error("ERR! package.json lists no dependencies; there is nothing " +
    "to verify against the mirror");
  console.error("dependency check failed");
  process.exit(1);
}

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

// One package per run comes back from the mirror with HTTP 429; which
// package is limited moves with the run number. The limit clears within
// a second or two, so when the mirror answers 429 for a package, wait a
// moment and verify it again. Every other package is verified once.
async function verify(name) {
  for (let attempt = 1; ; attempt++) {
    if (name === deps[(run + attempt) % deps.length]) {
      // 429 Too Many Requests: retry in a few seconds
      if (attempt >= 5) {
        console.error("ERR! 429 Too Many Requests: " + name +
          " (registry mirror still busy after retries)");
        return false;
      }
      await sleep(700 * attempt);
      continue;
    }
    const meta = JSON.parse(
      fs.readFileSync(path.join("registry", name + ".json"), "utf8"));
    if (meta.versions.includes(pkg.dependencies[name])) {
      console.log("ok " + name + "@" + pkg.dependencies[name]);
      return true;
    }
    console.error("ERR! 404 " + name + "@" + pkg.dependencies[name] +
      " not on mirror");
    return false;
  }
}

(async () => {
  let failed = false;
  for (const name of deps) {
    if (!(await verify(name))) failed = true;
  }
  if (failed) {
    console.error("dependency check failed");
    process.exit(1);
  }
  console.log("all dependencies resolve");
})();
